import React, { useState } from 'react';
import { FaPlane, FaCalendarAlt, FaExchangeAlt } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';

const FlightSearch = ({ departure, destination, dates }) => {
  const { theme } = useTheme();
  const [isLoading, setIsLoading] = useState(false);
  const [searchResults, setSearchResults] = useState(null);
  const [error, setError] = useState(null);

  const searchFlights = async () => {
    if (!departure || !destination || !dates) {
      setError('Please select departure, destination, and dates first');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // In a real implementation, you would call your flight search API here
      // For now, we'll simulate a response
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      // Simulated flight results
      setSearchResults([
        {
          airline: 'Sample Airlines',
          flightNumber: 'SA123',
          departure: {
            time: '10:00 AM',
            airport: departure.name
          },
          arrival: {
            time: '2:00 PM',
            airport: destination.name
          },
          duration: '4h 00m',
          price: 299,
          stops: 0
        },
        {
          airline: 'Another Airlines',
          flightNumber: 'AA456',
          departure: {
            time: '2:30 PM',
            airport: departure.name
          },
          arrival: {
            time: '7:30 PM',
            airport: destination.name
          },
          duration: '5h 00m',
          price: 249,
          stops: 1
        }
      ]);
    } catch (err) {
      setError('Failed to search for flights');
      console.error('Flight search error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center space-x-2">
        <FaPlane style={{ color: theme.primary }} className="text-xl" />
        <h3 className="text-lg font-medium" style={{ color: theme.text }}>
          Flight Search
        </h3>
      </div>

      {/* Flight Route Summary */}
      <div className="p-4 rounded-lg" style={{ backgroundColor: theme.background }}>
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <div className="text-sm" style={{ color: theme.textLight }}>
              From
            </div>
            <div className="text-lg font-medium" style={{ color: theme.text }}>
              {departure?.name || 'Select departure'}
            </div>
          </div>
          <FaExchangeAlt style={{ color: theme.primary }} className="text-xl" />
          <div className="space-y-1 text-right">
            <div className="text-sm" style={{ color: theme.textLight }}>
              To
            </div>
            <div className="text-lg font-medium" style={{ color: theme.text }}>
              {destination?.name || 'Select destination'}
            </div>
          </div>
        </div>
      </div>

      {/* Search Button */}
      <button
        onClick={searchFlights}
        disabled={!departure || !destination || !dates || isLoading}
        className={`w-full p-4 rounded-lg flex items-center justify-center space-x-2 transition-colors ${
          departure && destination && dates && !isLoading
            ? 'hover:opacity-90'
            : 'opacity-50 cursor-not-allowed'
        }`}
        style={{ 
          backgroundColor: theme.primary,
          color: theme.background
        }}
      >
        {isLoading ? (
          <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent" />
        ) : (
          <>
            <FaPlane className="text-xl" />
            <span>Search Flights</span>
          </>
        )}
      </button>

      {/* Error Message */}
      {error && (
        <div className="text-sm" style={{ color: theme.primary }}>
          {error}
        </div>
      )}

      {/* Search Results */}
      {searchResults && (
        <div className="space-y-4">
          {searchResults.map((flight, index) => (
            <div
              key={index}
              className="p-4 rounded-lg transition-colors hover:bg-opacity-10"
              style={{ 
                backgroundColor: theme.background,
                border: `1px solid ${theme.border}`,
                ':hover': {
                  backgroundColor: theme.primary
                }
              }}
            >
              <div className="flex items-center justify-between mb-2">
                <div className="font-medium" style={{ color: theme.text }}>
                  {flight.airline} - {flight.flightNumber}
                </div>
                <div className="font-medium" style={{ color: theme.primary }}>
                  {formatCurrency(flight.price)}
                </div>
              </div>
              <div className="flex items-center justify-between text-sm">
                <div style={{ color: theme.textLight }}>
                  {flight.departure.time} - {flight.arrival.time}
                </div>
                <div style={{ color: theme.textLight }}>
                  {flight.duration} {flight.stops === 0 ? '(Non-stop)' : `(${flight.stops} stop${flight.stops > 1 ? 's' : ''})`}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default FlightSearch;
